namespace KivotosMod.Content.Tablet.Delivery {
 public static class TabletDeliveryOrderSystem {
 public sealed record Order(Terraria.Player Owner,List<Terraria.Item> Items,Action Complete);
 public static Dictionary<int,Order> Orders=new();public static int Queued;
 public static int Enqueue(Terraria.Player p,List<Terraria.Item> gifts,Action complete=null){int id=++Queued;Orders[id]=new(p,gifts,complete);return id;}
 public static void CancelMailOrder(int id,Terraria.Player p){if(Orders.TryGetValue(id,out var order)&&order.Owner==p)Orders.Remove(id);}
 }
